import{_ as i,c as t,o as n,ae as l}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"AI Settings Panel User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Assistant/chat-settings.md","filePath":"Assistant/chat-settings.md"}'),o={name:"Assistant/chat-settings.md"};function a(s,e,r,u,c,h){return n(),t("div",null,e[0]||(e[0]=[l('<h1 id="ai-settings-panel-user-guide" tabindex="-1">AI Settings Panel User Guide <a class="header-anchor" href="#ai-settings-panel-user-guide" aria-label="Permalink to &quot;AI Settings Panel User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-settings-panel-user-guide">AI Settings Panel User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-ai-settings">Accessing AI Settings</a></li><li><a href="#ai-settings-panel-overview">AI Settings Panel Overview</a></li><li><a href="#blueprint-management">Blueprint Management</a><ul><li><a href="#loading-blueprints">Loading Blueprints</a></li><li><a href="#saving-blueprint-changes">Saving Blueprint Changes</a></li><li><a href="#viewing-blueprint-differences">Viewing Blueprint Differences</a></li><li><a href="#secure-blueprints">Secure Blueprints</a></li></ul></li><li><a href="#ai-instructions">AI Instructions</a></li><li><a href="#ai-model-configuration">AI Model Configuration</a><ul><li><a href="#model-selection">Model Selection</a></li><li><a href="#ai-mode">AI Mode</a></li><li><a href="#web-tools">Web Tools</a></li></ul></li><li><a href="#model-settings">Model Settings</a><ul><li><a href="#general-knowledge">General Knowledge</a></li><li><a href="#citations">Citations</a></li><li><a href="#content-filters">Content Filters</a></li></ul></li><li><a href="#knowledge-sources">Knowledge Sources</a><ul><li><a href="#knowledge-bases">Knowledge Bases</a></li><li><a href="#content-selection">Content Selection</a></li><li><a href="#search-configuration">Search Configuration</a></li><li><a href="#web-pages">Web Pages</a></li></ul></li><li><a href="#advanced-features">Advanced Features</a><ul><li><a href="#options-menu">Options Menu</a></li><li><a href="#blueprint-ownership">Blueprint Ownership</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Settings Panel provides comprehensive control over how the AI Assistant functions, including its knowledge sources, behavior, and response style. This sidebar interface allows you to configure AI settings for the current session, load saved Blueprints, and customize the AI&#39;s capabilities to best suit your needs. This guide explains how to use each setting to optimize your AI interactions.</p><h2 id="accessing-ai-settings" tabindex="-1">Accessing AI Settings <a class="header-anchor" href="#accessing-ai-settings" aria-label="Permalink to &quot;Accessing AI Settings&quot;">​</a></h2><p>The AI Settings Panel is accessible from the main AI Assistant interface:</p><ol><li>Click the settings icon in the header area of the AI Assistant</li><li>The settings panel opens as a sidebar on the right side of the screen</li><li>All changes made in this panel apply to the current session</li></ol><h2 id="ai-settings-panel-overview" tabindex="-1">AI Settings Panel Overview <a class="header-anchor" href="#ai-settings-panel-overview" aria-label="Permalink to &quot;AI Settings Panel Overview&quot;">​</a></h2><p>The Settings Panel is organized into several key sections:</p><ol><li><strong>Header</strong> - Contains the title and Options menu</li><li><strong>Blueprint</strong> - Load, save, and manage Blueprints</li><li><strong>Instructions</strong> - Configure AI behavior through system prompts</li><li><strong>AI Model</strong> - Select and configure the AI foundation model</li><li><strong>Web Tools</strong> - Enable web search and news capabilities</li><li><strong>Model Settings</strong> - Configure AI response parameters</li><li><strong>Knowledge Sources</strong> - Select content for the AI to reference</li></ol><h2 id="blueprint-management" tabindex="-1">Blueprint Management <a class="header-anchor" href="#blueprint-management" aria-label="Permalink to &quot;Blueprint Management&quot;">​</a></h2><h3 id="loading-blueprints" tabindex="-1">Loading Blueprints <a class="header-anchor" href="#loading-blueprints" aria-label="Permalink to &quot;Loading Blueprints&quot;">​</a></h3><p>To use a saved Blueprint configuration:</p><ol><li>Click the dropdown icon in the Blueprint section</li><li>A popup appears with available Blueprints</li><li>Optionally use the search box to filter Blueprints</li><li>Click on a Blueprint to load its settings</li><li>All settings in the panel update to match the selected Blueprint</li></ol><p>Each Blueprint includes:</p><ul><li>Avatar with initials</li><li>Blueprint name</li><li>Brief description</li><li>All associated AI settings</li></ul><h3 id="saving-blueprint-changes" tabindex="-1">Saving Blueprint Changes <a class="header-anchor" href="#saving-blueprint-changes" aria-label="Permalink to &quot;Saving Blueprint Changes&quot;">​</a></h3><p>When you modify settings from a loaded Blueprint:</p><ol><li>A &quot;Blueprint Changed&quot; warning appears</li><li>The warning indicates settings no longer match the original Blueprint</li><li>Click the &quot;Save&quot; button in the warning or at the top of the Blueprint section</li><li>Confirm saving in the dialog that appears</li><li>The Blueprint is updated with your current settings</li></ol><p><strong>Note</strong>: You must have ownership permissions to save changes to a Blueprint.</p><h3 id="viewing-blueprint-differences" tabindex="-1">Viewing Blueprint Differences <a class="header-anchor" href="#viewing-blueprint-differences" aria-label="Permalink to &quot;Viewing Blueprint Differences&quot;">​</a></h3><p>To see what changes you&#39;ve made to a Blueprint:</p><ol><li>Click &quot;Show Diff&quot; in the warning message when a Blueprint has been modified</li><li>A dialog opens showing a comparison between: <ul><li>Original Blueprint settings</li><li>Current modified settings</li></ul></li><li>Review the differences before deciding to save</li></ol><h3 id="secure-blueprints" tabindex="-1">Secure Blueprints <a class="header-anchor" href="#secure-blueprints" aria-label="Permalink to &quot;Secure Blueprints&quot;">​</a></h3><p>Some Blueprints may be marked as secure:</p><ol><li>Secure Blueprints show a lockout screen when you don&#39;t have ownership</li><li>The message indicates &quot;The author of this Blueprint has made the settings a secret&quot;</li><li>You can still use the Blueprint but cannot view or edit its settings</li><li>Only owners of the Blueprint can see and modify secure settings</li></ol><h2 id="ai-instructions" tabindex="-1">AI Instructions <a class="header-anchor" href="#ai-instructions" aria-label="Permalink to &quot;AI Instructions&quot;">​</a></h2><p>The Instructions section controls the AI&#39;s behavior through system prompts:</p><ol><li>View the current instructions in the text area</li><li>Click the pencil icon to open the full Instructions editor</li><li>In the editor: <ul><li>Read guidance about effective instructions</li><li>Edit the text in the large text area</li><li>Instructions guide the AI on how to respond, its role, and limitations</li></ul></li></ol><p>Best practices for instructions:</p><ul><li>Be specific about the AI&#39;s role</li><li>Define any specialized knowledge domains</li><li>Set boundaries for what the AI should/shouldn&#39;t do</li><li>Include response format preferences</li><li>Keep instructions clear and concise</li></ul><h2 id="ai-model-configuration" tabindex="-1">AI Model Configuration <a class="header-anchor" href="#ai-model-configuration" aria-label="Permalink to &quot;AI Model Configuration&quot;">​</a></h2><h3 id="model-selection" tabindex="-1">Model Selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model Selection&quot;">​</a></h3><p>To select the AI foundation model:</p><ol><li>Click on the model name box</li><li>The LLM selector dialog opens</li><li>Choose from available models (Claude 3 Haiku, Sonnet, etc.)</li><li>Selected model appears in the model box with logo</li><li>Different models offer varying capabilities, speeds, and costs</li></ol><h3 id="ai-mode" tabindex="-1">AI Mode <a class="header-anchor" href="#ai-mode" aria-label="Permalink to &quot;AI Mode&quot;">​</a></h3><p>Configure how the AI processes and responds to queries:</p><ol><li>Use the AI Mode dropdown to select: <ul><li><strong>Question &amp; Answers</strong>: Standard Q&amp;A functionality</li><li><strong>Agentic</strong>: More autonomous problem-solving abilities</li><li><strong>Tools</strong>: Enables the use of specific tools and functions</li></ul></li></ol><h3 id="web-tools" tabindex="-1">Web Tools <a class="header-anchor" href="#web-tools" aria-label="Permalink to &quot;Web Tools&quot;">​</a></h3><p>Control the AI&#39;s access to external information:</p><ol><li><p><strong>Live Web Lookup</strong>:</p><ul><li>Toggle the &quot;Live Web&quot; button on/off</li><li>When enabled, adjust the number of search results (0-25) by clicking the badge</li><li>Higher numbers provide more comprehensive but potentially less focused results</li></ul></li><li><p><strong>Live News Lookup</strong>:</p><ul><li>Toggle the &quot;Live News&quot; button on/off</li><li>When enabled, click the badge to configure: <ul><li>Number of news results (0-50)</li><li>Time range for news (days in the past)</li></ul></li><li>Useful for questions about current events and recent developments</li></ul></li></ol><h2 id="model-settings" tabindex="-1">Model Settings <a class="header-anchor" href="#model-settings" aria-label="Permalink to &quot;Model Settings&quot;">​</a></h2><h3 id="general-knowledge" tabindex="-1">General Knowledge <a class="header-anchor" href="#general-knowledge" aria-label="Permalink to &quot;General Knowledge&quot;">​</a></h3><p>Control whether the AI can use its pre-trained knowledge:</p><ol><li>Toggle &quot;Allow LLM Answers&quot; on/off</li><li>When ON: AI can answer using both its built-in knowledge and your content</li><li>When OFF: AI will only use information from your selected content sources</li><li>Useful for controlling exactly where information comes from</li></ol><h3 id="citations" tabindex="-1">Citations <a class="header-anchor" href="#citations" aria-label="Permalink to &quot;Citations&quot;">​</a></h3><p>Manage how the AI attributes information sources:</p><ol><li>Toggle &quot;Citations&quot; on/off</li><li>When ON: AI includes numbered references and source information</li><li>When OFF: AI provides answers without explicit source attribution</li><li>Citations help verify information accuracy and source reliability</li></ol><h3 id="content-filters" tabindex="-1">Content Filters <a class="header-anchor" href="#content-filters" aria-label="Permalink to &quot;Content Filters&quot;">​</a></h3><p>Control content appropriateness:</p><ol><li>Toggle &quot;Profanity&quot; allowed/blocked</li><li>When blocked: AI filters out inappropriate language</li><li>When allowed: AI may include language that would otherwise be filtered</li><li>Consider your organization&#39;s policies when configuring this setting</li></ol><h2 id="knowledge-sources" tabindex="-1">Knowledge Sources <a class="header-anchor" href="#knowledge-sources" aria-label="Permalink to &quot;Knowledge Sources&quot;">​</a></h2><h3 id="knowledge-bases" tabindex="-1">Knowledge Bases <a class="header-anchor" href="#knowledge-bases" aria-label="Permalink to &quot;Knowledge Bases&quot;">​</a></h3><p>Select knowledge repositories for the AI to use:</p><ol><li>Expand the &quot;Knowledge Bases&quot; accordion</li><li>View currently selected Knowledge Bases and content as chips</li><li>Click &quot;Edit Content&quot; to open the content selection dialog</li><li>In the dialog: <ul><li>Left panel: Select Knowledge Bases to include</li><li>Right panel: Choose specific content items</li><li>Use search boxes to filter options</li></ul></li></ol><h3 id="content-selection" tabindex="-1">Content Selection <a class="header-anchor" href="#content-selection" aria-label="Permalink to &quot;Content Selection&quot;">​</a></h3><p>In the content selection dialog:</p><ol><li><p><strong>Knowledge Bases</strong>: Select entire knowledge repositories</p><ul><li>Each KB contains multiple documents or content items</li><li>Selecting a KB includes all its content</li></ul></li><li><p><strong>Assigned Content</strong>: Choose specific individual content items</p><ul><li>More granular control over exactly what information is included</li><li>Useful for targeted knowledge needs</li></ul></li></ol><h3 id="search-configuration" tabindex="-1">Search Configuration <a class="header-anchor" href="#search-configuration" aria-label="Permalink to &quot;Search Configuration&quot;">​</a></h3><p>Fine-tune how the AI searches knowledge sources:</p><ol><li><p><strong>KB Search Results</strong>: Set the number of results (1-500)</p><ul><li>Higher values provide more comprehensive coverage</li><li>Lower values focus on the most relevant content</li></ul></li><li><p><strong>Minimum Match Score</strong>: Set the relevance threshold (1-500%)</p><ul><li>Higher values only include highly relevant content</li><li>Lower values include more content with lower relevance</li><li>Standard setting is around 60-70%</li></ul></li></ol><h3 id="web-pages" tabindex="-1">Web Pages <a class="header-anchor" href="#web-pages" aria-label="Permalink to &quot;Web Pages&quot;">​</a></h3><p>Add specific web pages as information sources:</p><ol><li>Expand the &quot;Web Pages&quot; accordion</li><li>View any currently added web pages</li><li>Click the &quot;+&quot; button to add a new web page</li><li>Enter the complete URL (including https://)</li><li>Up to 15 web pages can be added</li><li>Remove pages by clicking the trash icon</li><li>The AI will crawl these pages for information during conversations</li></ol><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="options-menu" tabindex="-1">Options Menu <a class="header-anchor" href="#options-menu" aria-label="Permalink to &quot;Options Menu&quot;">​</a></h3><p>Access additional functionality through the three-dot menu:</p><ol><li><strong>Show Settings Page</strong>: Open the full settings interface</li><li><strong>Save This Blueprint</strong>: Save current settings to the active Blueprint</li><li><strong>Copy to New Session</strong>: Create a new chat with current settings</li><li><strong>Create New Blueprint</strong>: Make a new Blueprint from current settings</li></ol><h3 id="blueprint-ownership" tabindex="-1">Blueprint Ownership <a class="header-anchor" href="#blueprint-ownership" aria-label="Permalink to &quot;Blueprint Ownership&quot;">​</a></h3><p>Blueprint permissions are based on ownership:</p><ol><li>Users can view and use any Blueprint</li><li>Only owners can: <ul><li>Modify and save changes to a Blueprint</li><li>View settings of secure Blueprints</li><li>Delete Blueprints they own</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective AI configuration:</p><ol><li><p><strong>Targeted Knowledge Selection</strong>:</p><ul><li>Select only relevant Knowledge Bases for your current task</li><li>Too many sources can dilute relevance</li><li>Too few may limit the AI&#39;s knowledge</li></ul></li><li><p><strong>Web Tools Balance</strong>:</p><ul><li>Enable web search for current information</li><li>Keep search results manageable (5-10)</li><li>Use news search when timeliness matters</li></ul></li><li><p><strong>Model Selection</strong>:</p><ul><li>Use faster models (Haiku) for simple questions and drafts</li><li>Use more capable models (Sonnet) for complex reasoning</li></ul></li><li><p><strong>Clear Instructions</strong>:</p><ul><li>Be specific about the AI&#39;s role and tone</li><li>Include examples of desired responses when possible</li><li>Update instructions for different use cases</li></ul></li><li><p><strong>Blueprint Management</strong>:</p><ul><li>Create different Blueprints for different tasks</li><li>Update Blueprints when knowledge bases change</li><li>Use secure settings for sensitive configurations</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Changes to settings not affecting AI responses</p><ul><li>Ensure you&#39;ve made changes in the current session</li><li>Try asking a new question related to your changes</li><li>Check if the correct Knowledge Bases are selected</li></ul><p><strong>Issue</strong>: Unable to save Blueprint changes</p><ul><li>Verify you have ownership of the Blueprint</li><li>Check for any error messages in toast notifications</li><li>Try refreshing the page and making changes again</li></ul><p><strong>Issue</strong>: Web search not providing current information</p><ul><li>Check that &quot;Live Web&quot; is toggled on</li><li>Verify the search results number is sufficient (5+)</li><li>Formulate questions that clearly ask for current information</li></ul><p><strong>Issue</strong>: Cannot view Blueprint settings</p><ul><li>It may be a secure Blueprint that you don&#39;t own</li><li>Request access from the Blueprint owner</li><li>Create your own Blueprint with similar settings</li></ul><p><strong>Issue</strong>: Knowledge Base content not being used</p><ul><li>Check minimum match score isn&#39;t too high</li><li>Verify content is selected in the Content dialog</li><li>Try asking more specific questions related to the content</li></ul><p><strong>Issue</strong>: Model selection dialog not showing all models</p><ul><li>Some models may require specific permissions</li><li>Your organization may limit available models</li><li>Check with your administrator about model access</li></ul><hr><p>For additional assistance with AI settings, please contact your system administrator or refer to the platform documentation.</p>',90)]))}const p=i(o,[["render",a]]);export{g as __pageData,p as default};
